// @whimtex-brush VFX/Sparkle
// @param float _Sharpness = 5 [1 .. 12]
// @param color _Tint = (0.3, 0.6, 1, 1)

float4 BrushTip(float2 uv)
{
    float2 p = abs(uv * 2.0 - 1.0);
    float cross = pow(saturate(1.0 - sqrt(p.x) - sqrt(p.y)), _Sharpness);
    float glow = exp(-dot(p, p) * 35.0) * 0.2;
    float edge = 1.0 - smoothstep(0.8, 1.0, max(p.x, p.y));
    return float4(_Tint.rgb, saturate(cross + glow) * edge * _Tint.a);
}
